//! Box tree queries the public layout API does not offer.

use std::collections::HashMap;

use xbro_dom::NodeId;
use xbro_layout::{Fragment, LayoutBox, LayoutTree, Point, Rect, TextFragment};
use xbro_style::Visibility;

/// Recursion guard for box tree walks.
const MAX_DEPTH: usize = 2048;

/// The first box generated by `node` itself (not a pseudo-element), in the
/// order [`LayoutTree::node_rect`] searches, and whether it lies in a
/// `position: fixed` subtree (viewport coordinates).
pub(crate) fn node_box(tree: &LayoutTree, node: NodeId) -> Option<(&LayoutBox, bool)> {
    find(tree.root.as_ref()?, node, false, 0)
}

fn find(b: &LayoutBox, node: NodeId, in_fixed: bool, depth: usize) -> Option<(&LayoutBox, bool)> {
    if depth > MAX_DEPTH {
        return None;
    }
    let in_fixed = in_fixed || b.is_fixed();
    if b.node == Some(node) && b.pseudo.is_none() {
        return Some((b, in_fixed));
    }
    for line in &b.lines {
        for f in &line.fragments {
            if let Fragment::Atomic(a) = f {
                if let Some(found) = find(a, node, in_fixed, depth + 1) {
                    return Some(found);
                }
            }
        }
    }
    b.children
        .iter()
        .find_map(|c| find(c, node, in_fixed, depth + 1))
}

/// Like [`LayoutTree::node_rect`] (border box of the first box or fragment
/// generated by `node`), with whether it lies in a `position: fixed`
/// subtree, where rects are in viewport coordinates.
pub(crate) fn node_rect_fixed(tree: &LayoutTree, node: NodeId) -> Option<(Rect, bool)> {
    rect_in(tree.root.as_ref()?, node, false, 0)
}

fn rect_in(b: &LayoutBox, node: NodeId, in_fixed: bool, depth: usize) -> Option<(Rect, bool)> {
    if depth > MAX_DEPTH {
        return None;
    }
    let in_fixed = in_fixed || b.is_fixed();
    if b.node == Some(node) && b.pseudo.is_none() {
        return Some((b.border_box(), in_fixed));
    }
    for line in &b.lines {
        for f in &line.fragments {
            match f {
                Fragment::Text(t) if t.node == node => return Some((t.rect, in_fixed)),
                Fragment::InlineBox(ib) if ib.node == node => return Some((ib.rect, in_fixed)),
                Fragment::Atomic(a) => {
                    if let Some(found) = rect_in(a, node, in_fixed, depth + 1) {
                        return Some(found);
                    }
                }
                _ => {}
            }
        }
    }
    b.children
        .iter()
        .find_map(|c| rect_in(c, node, in_fixed, depth + 1))
}

/// All text fragments in the order of [`LayoutTree::text_fragments`] (paint
/// order), each with whether it lies in a `position: fixed` subtree
/// (viewport coordinates).
pub(crate) fn text_fragments_fixed(tree: &LayoutTree) -> Vec<(&TextFragment, bool)> {
    let mut out = Vec::new();
    if let Some(root) = &tree.root {
        collect_text(root, false, &mut out, 0);
    }
    out
}

fn collect_text<'a>(
    b: &'a LayoutBox,
    in_fixed: bool,
    out: &mut Vec<(&'a TextFragment, bool)>,
    depth: usize,
) {
    if depth > MAX_DEPTH {
        return;
    }
    let in_fixed = in_fixed || b.is_fixed();
    // In-flow block children paint before the inline content of a box.
    for c in b.children.iter().filter(|c| !c.style.is_out_of_flow()) {
        collect_text(c, in_fixed, out, depth + 1);
    }
    for line in &b.lines {
        for f in &line.fragments {
            match f {
                Fragment::Text(t) => out.push((t, in_fixed)),
                Fragment::Atomic(a) => collect_text(a, in_fixed, out, depth + 1),
                Fragment::InlineBox(_) => {}
            }
        }
    }
    for c in b.children.iter().filter(|c| c.style.is_out_of_flow()) {
        collect_text(c, in_fixed, out, depth + 1);
    }
}

/// Most backdrops reported by [`fixed_backdrops`].
const MAX_BACKDROPS: usize = 64;

/// Border boxes (viewport coordinates) of the `position: fixed` boxes that
/// paint a background, hiding the content that scrolls under them.
pub(crate) fn fixed_backdrops(tree: &LayoutTree) -> Vec<Rect> {
    let mut out = Vec::new();
    if let Some(root) = &tree.root {
        collect_backdrops(root, &mut out, 0);
    }
    out
}

fn collect_backdrops(b: &LayoutBox, out: &mut Vec<Rect>, depth: usize) {
    if depth > MAX_DEPTH || out.len() >= MAX_BACKDROPS {
        return;
    }
    let style = &b.style;
    if b.is_fixed()
        && style.visibility == Visibility::Visible
        && style.opacity > 0.0
        && (!style.background_color.is_transparent() || style.background_image.is_some())
    {
        let r = b.border_box();
        if r.width > 0.0 && r.height > 0.0 && r.x.is_finite() && r.y.is_finite() {
            out.push(r);
        }
    }
    for line in &b.lines {
        for f in &line.fragments {
            if let Fragment::Atomic(a) = f {
                collect_backdrops(a, out, depth + 1);
            }
        }
    }
    for c in &b.children {
        collect_backdrops(c, out, depth + 1);
    }
}

/// Where a node is rendered: see [`node_rects`].
#[derive(Copy, Clone, Debug, PartialEq)]
pub(crate) struct NodeRects {
    /// The first box or fragment generated by the node, in box tree order.
    pub first: Rect,
    /// The last one (the last line of a wrapped inline element or text).
    pub last: Rect,
    /// In a `position: fixed` subtree (viewport coordinates).
    pub fixed: bool,
    /// Inline-level (text, inline box or atomic inline) rather than a block box.
    pub inline: bool,
}

/// The boxes and fragments of every node that generates any, collected in
/// a single walk of the box tree. Generated content (pseudo-elements) is
/// attributed to no node.
pub(crate) fn node_rects(tree: &LayoutTree) -> HashMap<NodeId, NodeRects> {
    let mut out = HashMap::new();
    if let Some(root) = &tree.root {
        collect_rects(root, false, false, &mut out, 0);
    }
    out
}

fn record(
    out: &mut HashMap<NodeId, NodeRects>,
    node: NodeId,
    rect: Rect,
    fixed: bool,
    inline: bool,
) {
    out.entry(node)
        .and_modify(|r| r.last = rect)
        .or_insert(NodeRects {
            first: rect,
            last: rect,
            fixed,
            inline,
        });
}

fn collect_rects(
    b: &LayoutBox,
    in_fixed: bool,
    inline: bool,
    out: &mut HashMap<NodeId, NodeRects>,
    depth: usize,
) {
    if depth > MAX_DEPTH {
        return;
    }
    let in_fixed = in_fixed || b.is_fixed();
    if let (Some(node), None) = (b.node, b.pseudo) {
        record(out, node, b.border_box(), in_fixed, inline);
    }
    for line in &b.lines {
        for f in &line.fragments {
            match f {
                Fragment::Text(t) => record(out, t.node, t.rect, in_fixed, true),
                Fragment::InlineBox(ib) => record(out, ib.node, ib.rect, in_fixed, true),
                Fragment::Atomic(a) => collect_rects(a, in_fixed, true, out, depth + 1),
            }
        }
    }
    for c in &b.children {
        collect_rects(c, in_fixed, false, out, depth + 1);
    }
}

/// Content box (document coordinates for the scroll offset `scroll`) of
/// the box generated by `node`: for replaced elements, the area the image
/// is drawn into.
pub(crate) fn content_rect(tree: &LayoutTree, node: NodeId, scroll: Point) -> Option<Rect> {
    let (b, fixed) = node_box(tree, node)?;
    let mut r = b.content;
    if fixed {
        r.x += scroll.x;
        r.y += scroll.y;
    }
    Some(r)
}

#[cfg(test)]
mod tests {
    use super::*;
    use xbro_layout::{LayoutContext, NoImages, Size};
    use xbro_style::{compute_styles, StyleContext};
    use xbro_text::FontSystem;

    fn lay_out(html: &str) -> (xbro_dom::Document, LayoutTree) {
        let doc = xbro_html::parse_document(html);
        let styles = compute_styles(&doc, &[], &StyleContext::default());
        let fonts = FontSystem::new();
        let tree = xbro_layout::layout(&LayoutContext {
            document: &doc,
            styles: &styles,
            fonts: &fonts,
            replaced: &NoImages,
            viewport: Size::new(400.0, 300.0),
            focused: None,
        });
        (doc, tree)
    }

    #[test]
    fn fixed_boxes_are_converted_to_document_coordinates() {
        let (doc, tree) = lay_out(
            "<body style='margin:0;height:3000px'>\
             <div id=f style='position:fixed;top:10px;left:20px;width:5px;height:5px'></div>",
        );
        let f = doc.get_element_by_id("f").unwrap();
        let r = content_rect(&tree, f, Point::new(0.0, 500.0)).unwrap();
        assert_eq!((r.x, r.y), (20.0, 510.0));
        let (r, fixed) = node_rect_fixed(&tree, f).unwrap();
        assert!(fixed);
        assert_eq!(Some(r), tree.node_rect(f));
        let body = doc.body().unwrap();
        assert_eq!(node_rect_fixed(&tree, body).map(|(_, f)| f), Some(false));
    }

    #[test]
    fn text_fragments_keep_the_layout_order_and_flag_fixed_ones() {
        let (doc, tree) = lay_out(
            "<body style='margin:0'><p>one <span style='display:inline-block'>two</span></p>\
             <div style='position:fixed;top:0'>three <b style='position:absolute'>four</b></div>\
             <div style='float:left'>five</div><p style='position:absolute;top:50px'>six</p>",
        );
        let flagged = text_fragments_fixed(&tree);
        let plain = tree.text_fragments();
        assert_eq!(flagged.len(), plain.len());
        assert!(flagged
            .iter()
            .zip(&plain)
            .all(|((a, _), b)| std::ptr::eq(*a, *b)));
        let fixed: Vec<&str> = flagged
            .iter()
            .filter(|(_, fixed)| *fixed)
            .map(|(t, _)| t.text.trim())
            .collect();
        assert_eq!(fixed, ["three", "four"]);
        // Every rendered node is found, with its first and last rect.
        let rects = node_rects(&tree);
        let body = doc.body().unwrap();
        assert!(rects.get(&body).is_some_and(|r| !r.inline && !r.fixed));
        let b = doc.get_elements_by_tag_name("b")[0];
        assert!(rects.get(&b).is_some_and(|r| r.fixed));
    }

    #[test]
    fn finds_inline_and_block_boxes() {
        let (doc, tree) = lay_out(
            "<body style='margin:0'><div id=d style='padding:5px;border:2px solid'>\
             <span id=s style='display:inline-block;padding:3px;width:10px;height:10px'></span></div>",
        );
        let d = doc.get_element_by_id("d").unwrap();
        let s = doc.get_element_by_id("s").unwrap();
        let rd = content_rect(&tree, d, Point::ZERO).unwrap();
        assert_eq!((rd.x, rd.y), (7.0, 7.0));
        let rs = content_rect(&tree, s, Point::ZERO).unwrap();
        let border = tree.node_rect(s).unwrap();
        assert_eq!((rs.x - border.x, rs.width), (3.0, 10.0));
        assert!(content_rect(&tree, doc.root(), Point::ZERO).is_none());
    }
}
